const app=document.querySelector("#app"),money=value=>new Intl.NumberFormat("en-US",{style:"currency",currency:"USD",maximumFractionDigits:0}).format(value);
const session=JSON.parse(localStorage.getItem("1001-session")||"null");
const emptyFilters=()=>({q:"",brand:"",category:"",fuel:"",transmission:"",seller:"",opportunity:"",minPrice:"",maxPrice:"",minMileage:"",maxMileage:"",sort:""});
const recentSearchesKey="1001-recent-searches";
const state={vehicles:[],brands:[],agencies:[],brandCondition:"seminuevos",catalogType:"usados",showcaseCategory:"suv",sellStep:1,sellDraft:{},compare:new Set(),selectedBrands:new Set(),localFavorites:new Set(JSON.parse(localStorage.getItem("1001-favorites")||"[]")),recentSearches:JSON.parse(localStorage.getItem(recentSearchesKey)||"[]"),session,filters:emptyFilters(),reservation:{originQuery:"Cumbayá, Quito",selectedAgencyId:null}};

async function request(path,options={}){const headers={"content-type":"application/json",...(options.headers||{})};if(state.session?.token)headers.authorization=`Bearer ${state.session.token}`;const response=await fetch(path,{...options,headers});const data=await response.json();if(!response.ok)throw new Error(data.error||"No se pudo completar la solicitud");return data;}
function escapeHtml(value){return String(value??"").replace(/[&<>'"]/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[char]));}
function showToast(message){const toast=document.querySelector("#toast");toast.textContent=message;toast.classList.add("show");clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove("show"),2300);}
function navigate(path){history.pushState({},"",path);renderRoute();}
function setTitle(title){document.title=`${title} | 1001Carros.com`;const section=location.pathname==="/"?"inicio":["/catalogo","/nuevos","/seminuevos","/usados"].includes(location.pathname)?"comprar":location.pathname==="/vender"?"vender":"";document.querySelectorAll(".main-nav a").forEach(a=>a.classList.toggle("active",a.dataset.navSection===section));}

function carCard(car){const favorite=state.localFavorites.has(car.id);return `<article class="car-card">
  <a class="car-image" href="/vehiculo/${car.id}" data-route><img src="${escapeHtml(car.image)}" alt="${escapeHtml(car.brand)} ${escapeHtml(car.model)}" loading="lazy"><span class="badge ${car.badge==="Garantizado"?"green":""}">${escapeHtml(car.badge)}</span></a>
  <button class="favorite ${favorite?"saved":""}" type="button" data-favorite="${car.id}" aria-label="${favorite?"Quitar de":"Guardar en"} favoritos">${favorite?"♥":"♡"}</button>
  <div class="car-body"><p class="car-kicker">${escapeHtml(car.brand)} · ${escapeHtml(car.city)}</p><a href="/vehiculo/${car.id}" data-route><h3>${escapeHtml(car.brand.toUpperCase())} ${escapeHtml(car.model.toUpperCase())}</h3></a>
  <div class="spec-list"><span>${car.year}</span><span>${Number(car.mileage).toLocaleString("es-EC")} km</span><span>${escapeHtml(car.drive)}</span><span>${escapeHtml(car.transmission)}</span><span>${escapeHtml(car.fuel)}</span></div>
  <div class="car-price"><div><small>Precio</small><strong>${money(car.price)}</strong></div><p>Cuotas desde<b>${money(car.monthly)}/mes</b></p></div>
  <button class="compare-toggle ${state.compare.has(car.id)?"selected":""}" type="button" data-compare="${car.id}">${state.compare.has(car.id)?"✓ Seleccionado":"+ Comparar"}</button></div></article>`;}

function brandBrowser(){return `<section class="brand-browser"><h2>Marcas de carros destacadas en Ecuador</h2><div class="brand-tabs"><button type="button" class="${state.brandCondition==="seminuevos"?"active":""}" data-brand-condition="seminuevos">Seminuevos</button><button type="button" class="${state.brandCondition==="nuevos"?"active":""}" data-brand-condition="nuevos">Nuevos</button></div><div class="brand-track" id="brand-track">${state.brands.map(brand=>`<a class="brand-card" href="/catalogo?tipo=${state.brandCondition==="nuevos"?"nuevos":"usados"}" data-brand-catalog="${escapeHtml(brand.name)}"><strong>${escapeHtml(brand.name)}</strong><div class="brand-logo">${brand.logoSvg}</div><ul>${brand.models.map(model=>`<li>${escapeHtml(model)}</li>`).join("")}</ul></a>`).join("")}</div><div class="brand-controls"><span></span><button type="button" data-brand-scroll="-1" aria-label="Marcas anteriores">←</button><button type="button" data-brand-scroll="1" aria-label="Más marcas">→</button></div></section>`;}

function showcaseVehicleCard(car){const favorite=state.localFavorites.has(car.id),compared=state.compare.has(car.id),previous=Math.round(car.price*1.08/100)*100;return `<article class="showcase-car">
  <a class="showcase-image" href="/vehiculo/${car.id}" data-route><img src="${escapeHtml(car.image)}" alt="${escapeHtml(car.brand)} ${escapeHtml(car.model)}" loading="lazy">${car.condition==="nuevos"?'<span>Bonos especiales</span>':""}</a>
  <button class="showcase-favorite ${favorite?"saved":""}" type="button" data-favorite="${car.id}" aria-label="${favorite?"Quitar de":"Guardar en"} favoritos"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 3.5h12a1 1 0 0 1 1 1v16l-7-4-7 4v-16a1 1 0 0 1 1-1Z"/></svg></button>
  <div class="showcase-body"><a href="/vehiculo/${car.id}" data-route><h3>${escapeHtml(car.brand)} ${escapeHtml(car.model)}</h3></a><div class="showcase-price"><span><del>${money(previous)}</del><small>Precio anterior</small></span><strong>${money(car.price)}<small>Precio actual</small></strong></div>
  <div class="showcase-specs"><span>▧ ${car.year}</span><span>◉ ${Number(car.mileage).toLocaleString("es-EC")} km</span><span>◎ ${escapeHtml(car.drive)}</span><span>⌁ ${escapeHtml(car.transmission)}</span><span>▣ ${escapeHtml(car.fuel)}</span></div>
  <a class="showcase-more" href="/vehiculo/${car.id}" data-route>Ver más</a><button class="showcase-compare ${compared?"selected":""}" type="button" data-compare="${car.id}">Comparar <i>${compared?"✓":""}</i></button></div></article>`;}

function inventoryShowcase(){const tabs=[["suv","SUVs"],["automovil","Automóviles"],["camioneta","Camionetas"]],cars=state.vehicles.filter(car=>car.category===state.showcaseCategory);return `<section class="inventory-showcase" aria-label="Vehículos destacados por categoría"><aside class="inventory-promos"><a class="inventory-promo used-promo" href="/catalogo" data-route><div><h2>Seminuevos</h2><p>Carros con garantía de procedencia, mecánica y alistamiento listos para ti</p><span>Ver seminuevos</span></div></a><a class="inventory-promo new-promo" href="/catalogo?tipo=nuevos" data-route><div><img src="https://www.changanecuador.com/images/changan_logo.svg" alt="Changan nuevos"><h2>Nuevos</h2><p>Explora nuestro catálogo de carros nuevos y accede a financiamiento</p><span>Ver nuevos</span></div></a></aside><div class="inventory-browser"><div class="inventory-tabs" role="tablist" aria-label="Tipo de vehículo">${tabs.map(([value,label])=>`<button type="button" role="tab" aria-selected="${state.showcaseCategory===value}" class="${state.showcaseCategory===value?"active":""}" data-showcase-category="${value}">${label}</button>`).join("")}</div><div class="showcase-track" id="showcase-track">${cars.map(showcaseVehicleCard).join("")}</div><button class="showcase-arrow previous" type="button" data-showcase-scroll="-1" aria-label="Vehículos anteriores">‹</button><button class="showcase-arrow next" type="button" data-showcase-scroll="1" aria-label="Más vehículos">›</button></div></section>`;}

function normalized(value){return String(value||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase();}
const reservationOrigins=[
  {terms:["cumbaya","cumbayá","tumbaco","puembo"],label:"Cumbayá, Quito",lat:-0.1961,lng:-78.4309},
  {terms:["norte","carcelen","carcelén","cotocollao","granados","el inca"],label:"Norte de Quito",lat:-0.1379,lng:-78.4852},
  {terms:["sur","quitumbe","guamani","guamaní","villaflora"],label:"Sur de Quito",lat:-0.2873,lng:-78.5489},
  {terms:["quito","centro"],label:"Quito",lat:-0.1807,lng:-78.4678}
];
function reservationOrigin(query){const term=normalized(query);return reservationOrigins.find(origin=>origin.terms.some(key=>term.includes(normalized(key))))||reservationOrigins[0];}
function distanceKm(origin,agency){const radians=value=>value*Math.PI/180,earth=6371,dLat=radians(Number(agency.lat)-origin.lat),dLng=radians(Number(agency.lng)-origin.lng),a=Math.sin(dLat/2)**2+Math.cos(radians(origin.lat))*Math.cos(radians(Number(agency.lat)))*Math.sin(dLng/2)**2;return earth*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a));}
function agenciesByDistance(query=state.reservation.originQuery){const origin=reservationOrigin(query);return [...state.agencies].map(agency=>({...agency,distance:distanceKm(origin,agency)})).sort((a,b)=>a.distance-b.distance);}
function saveRecentSearch(query){const value=query.trim();if(!value)return;state.recentSearches=[value,...state.recentSearches.filter(item=>normalized(item)!==normalized(value))].slice(0,5);localStorage.setItem(recentSearchesKey,JSON.stringify(state.recentSearches));}
function homeSearchPanel(query=""){const term=query.trim(),needle=normalized(term);if(!term){if(state.recentSearches.length)return `<div class="home-search-panel" id="home-search-panel" role="region" aria-label="Búsquedas recientes"><h3>Reciente</h3>${state.recentSearches.map(item=>`<button type="button" class="search-panel-option" data-home-search="${escapeHtml(item)}"><span>${escapeHtml(item)}</span><b>↗</b></button>`).join("")}</div>`;const featured=[["SUV", "SUVs"],["Híbrido", "Híbridos y eléctricos"],["Camioneta", "Camionetas"],["Automóvil", "Autos para ciudad"]];return `<div class="home-search-panel" id="home-search-panel" role="region" aria-label="Explora el inventario"><h3>Destacados</h3>${featured.map(([query,label])=>`<button type="button" class="search-panel-option" data-home-search="${query}"><span>${label}</span><b>→</b></button>`).join("")}</div>`;}const matches=state.vehicles.filter(car=>normalized(`${car.brand} ${car.model} ${car.category} ${car.fuel} ${car.city}`).includes(needle)).slice(0,7);return `<div class="home-search-panel searching" id="home-search-panel" role="listbox" aria-label="Sugerencias de búsqueda"><button type="button" class="search-panel-query" data-home-search="${escapeHtml(term)}">Buscar <strong>“${escapeHtml(term)}”</strong><b>↵</b></button>${matches.length?`<h3>Vehículos disponibles</h3>${matches.map(car=>`<button type="button" class="search-panel-option vehicle-option" data-home-search="${escapeHtml(`${car.brand} ${car.model}`)}" role="option"><span><strong>${escapeHtml(car.brand)} ${escapeHtml(car.model)}</strong><small>${car.year} · ${escapeHtml(car.city)}</small></span><b>→</b></button>`).join("")}`:`<p class="search-panel-empty">No encontramos coincidencias. Prueba con marca, modelo o tipo de carro.</p>`}</div>`;}
function updateHomeSearchPanel(input){const wrap=input.closest(".reference-search-wrap"),existing=wrap?.querySelector("#home-search-panel");if(existing)existing.outerHTML=homeSearchPanel(input.value);}
function partnerExplorer(compact=false){const stores=[{id:"1001",label:"1001Carros.com",copy:"Seminuevos con garantía",count:state.vehicles.filter(car=>car.featured).length,mark:"1001",car:state.vehicles.find(car=>car.featured)},{id:"autosok",label:"Autos Ok",copy:"Autos listos para ti",count:state.vehicles.filter(car=>!car.featured).length,mark:"OK",car:state.vehicles.find(car=>!car.featured)},{id:"changan",label:"Changan",copy:"Nuevos 0 km",count:state.vehicles.filter(car=>car.condition==="nuevos"&&normalized(car.brand).includes("changan")).length,mark:"CHANGAN",car:state.vehicles.find(car=>car.condition==="nuevos"&&normalized(car.brand).includes("changan"))}];return `<section class="partner-explorer ${compact?"catalog-partners":""}" aria-label="Explora nuestros aliados">${compact?"":"<h2>Encuentra tu próximo carro</h2>"}<div class="partner-explorer-grid">${stores.map(store=>`<button type="button" class="partner-explorer-card ${store.id}" data-shop-source="${store.id}"><span class="partner-explorer-image">${store.car?`<img src="${escapeHtml(store.car.image)}" alt="" loading="lazy">`:`<i>${store.mark}</i>`}</span><span class="partner-explorer-content"><strong>${store.label}</strong><small>${store.copy}</small><em>${store.count} disponibles</em></span><b aria-hidden="true">→</b></button>`).join("")}</div></section>`;}
function homePage(){setTitle("Inicio");return `<section class="hero"><div class="hero-image"></div><div class="hero-signal"></div><div class="hero-content">
  <div class="reference-search-wrap"><h2>Únicos con garantía legal y mecánica</h2><form class="reference-search home-search" role="search"><label><svg aria-hidden="true" viewBox="0 0 24 24"><circle cx="11" cy="11" r="6.5"></circle><path d="m16 16 4 4"></path></svg><span class="sr-only">Busca tu carro</span><input name="q" placeholder="¿Qué carro estás buscando?" autocomplete="off" aria-autocomplete="list" aria-controls="home-search-panel" aria-expanded="false"></label><button type="submit">Busca tu carro</button></form>${homeSearchPanel()}</div></div>
  <div class="hero-stats"><div><strong>${state.vehicles.length||"+400"}</strong><span>carros en este demo</span></div><div><strong>15 años</strong><span>moviendo Ecuador</span></div><div><strong>6</strong><span>agencias demo</span></div></div></section>
  ${partnerExplorer()}
  ${brandBrowser()}
  ${inventoryShowcase()}
  <section class="quick-links"><a href="/catalogo" data-route><span class="quick-icon">✓</span><span><strong>Seminuevos garantizados</strong><small>Inspeccionados y listos</small></span><b>→</b></a><a href="/vender" data-route><span class="quick-icon">↗</span><span><strong>Vende tu carro</strong><small>Recibe una oferta sin vueltas</small></span><b>→</b></a><a href="/financiamiento" data-route><span class="quick-icon">$</span><span><strong>Calcula tu cuota</strong><small>Opciones para tu presupuesto</small></span><b>→</b></a></section>
  <section class="home-promise"><div><p class="eyebrow">Garantía de satisfacción</p><h2>7 días o 300 km<br>para enamorarte.</h2><p>Si el carro no es para ti, puedes devolverlo bajo las condiciones del programa.</p></div><div class="promise-list"><span><b>150</b> puntos de inspección</span><span><b>1 año</b> de garantía mecánica</span><span><b>$500</b> para reservarlo</span></div></section>`;}

function countBy(field,value){return state.vehicles.filter(car=>String(car[field]).toLowerCase()===String(value).toLowerCase()).length;}
function filterChoice(key,value,label,icon=""){const active=state.filters[key]===value;return `<button class="filter-choice ${active?"active":""}" type="button" data-catalog-filter="${key}" data-filter-value="${value}" aria-pressed="${active}">${icon}<span>${label}</span></button>`;}
function typeIcon(kind){const shapes={automovil:'<path d="M3 15h18l-1.7-5.1-4.1-2.6H8.8L4.7 10 3 15Z"/><circle cx="7" cy="16" r="2"/><circle cx="17" cy="16" r="2"/>',camioneta:'<path d="M2.5 14.5h19V9h-7V6.5H7L3 10l-.5 4.5Z"/><circle cx="7" cy="16" r="2"/><circle cx="18" cy="16" r="2"/>',furgoneta:'<path d="M3 7h13l4 4v4H3V7Z"/><path d="M16 8v4h4"/><circle cx="7" cy="16" r="2"/><circle cx="17" cy="16" r="2"/>',suv:'<path d="M3 14.5h18l-1-5-4-3H9L4 9.5l-1 5Z"/><circle cx="7" cy="16" r="2"/><circle cx="18" cy="16" r="2"/>'};return `<svg class="vehicle-type-icon" viewBox="0 0 24 20" aria-hidden="true">${shapes[kind]||shapes.suv}</svg>`;}
function filtersMarkup(){const prices=state.vehicles.map(x=>x.price),mileages=state.vehicles.map(x=>x.mileage),minPrice=Math.floor(Math.min(...prices)/500)*500,maxPrice=Math.ceil(Math.max(...prices)/500)*500,maxMileage=Math.ceil(Math.max(...mileages)/1000)*1000,brandLabel=state.selectedBrands.size===1?[...state.selectedBrands][0]:state.selectedBrands.size?`${state.selectedBrands.size} marcas seleccionadas`:"Añadir modelo y marca";return `<aside class="filter-panel"><div class="filter-title"><strong><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 3v7m0 4v7M18 3v3m0 4v11M3 10h6m6-4h6"></path></svg>Filtro</strong><button type="button" data-clear-filters>Limpiar</button></div>
  <details open><summary>Tipo de vehículo</summary><div class="vehicle-type-grid">${[["automovil","Automóvil"],["camioneta","Camioneta"],["furgoneta","Furgoneta"],["suv","SUV"]].map(([value,label])=>filterChoice("category",value,`${label} (${countBy("category",value)})`,typeIcon(value))).join("")}</div></details>
  <details open><summary>Modelo/marca</summary><button class="brand-select" type="button" data-brand-picker aria-haspopup="dialog"><span>＋</span><i>${escapeHtml(brandLabel)}</i><b>›</b></button></details>
  <details open><summary>Precio</summary><div class="range-values"><label>Desde<span><b>$</b><input name="minPrice" type="number" min="${minPrice}" max="${maxPrice}" value="${state.filters.minPrice}" placeholder="${minPrice}"></span></label><label>Hasta<span><b>$</b><input name="maxPrice" type="number" min="${minPrice}" max="${maxPrice}" value="${state.filters.maxPrice}" placeholder="${maxPrice}"></span></label></div><div class="double-range"><input type="range" min="${minPrice}" max="${maxPrice}" step="500" value="${state.filters.minPrice||minPrice}" data-range-key="minPrice"><input type="range" min="${minPrice}" max="${maxPrice}" step="500" value="${state.filters.maxPrice||maxPrice}" data-range-key="maxPrice"></div><div class="price-links"><button type="button" data-clear-price>Ver rangos de precios</button><a href="/financiamiento" data-route>$ Financiamiento</a></div></details>
  <details open><summary>Oportunidades para ti</summary><div class="opportunity-options">${filterChoice("opportunity","bonos","Bonos Especiales")}${filterChoice("opportunity","ciclo","Ciclo 1001carros.com")}</div></details>
  <details open><summary>Kilometraje</summary><div class="range-values"><label>* Min<span><input name="minMileage" type="number" min="0" max="${maxMileage}" value="${state.filters.minMileage}" placeholder="0"></span></label><label>* Max<span><input name="maxMileage" type="number" min="0" max="${maxMileage}" value="${state.filters.maxMileage}" placeholder="${maxMileage}"></span></label></div><div class="double-range"><input type="range" min="0" max="${maxMileage}" step="1000" value="${state.filters.minMileage||0}" data-range-key="minMileage"><input type="range" min="0" max="${maxMileage}" step="1000" value="${state.filters.maxMileage||maxMileage}" data-range-key="maxMileage"></div></details>
  <details open><summary>Combustible</summary><div class="compact-filter-grid">${["Diesel","Eléctrico","Gasolina","Híbrido"].map(value=>filterChoice("fuel",value,`▧ ${value} (${countBy("fuel",value)})`)).join("")}</div></details>
  <details open><summary>Transmisión</summary><div class="compact-filter-grid">${["Automática","Manual"].map(value=>filterChoice("transmission",value,`♨ ${value} (${countBy("transmission",value)})`)).join("")}</div></details></aside>`;}

function catalogCarCard(car){const favorite=state.localFavorites.has(car.id),compared=state.compare.has(car.id),seller=car.featured?"1001CARROS.COM":"AUTOS OK",bonus=car.condition==="nuevos"||car.badge==="Nuevo",guaranteed=car.badge==="Garantizado";return `<article class="catalog-car-card"><div class="catalog-car-image"><a href="/vehiculo/${car.id}" data-route><img src="${escapeHtml(car.image)}" alt="${escapeHtml(car.brand)} ${escapeHtml(car.model)}" loading="lazy"></a>${bonus?'<span class="special-bonus">BONOS ESPECIALES</span>':""}<button class="catalog-favorite ${favorite?"saved":""}" type="button" data-favorite="${car.id}" aria-label="${favorite?"Quitar de":"Guardar en"} favoritos"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 3.5h12a1 1 0 0 1 1 1v16l-7-4-7 4v-16a1 1 0 0 1 1-1Z"></path></svg></button><span class="catalog-360">⟳ 360°</span></div><div class="catalog-car-body"><span class="seller-tag ${car.featured?"":"autos-ok"}">${seller}</span><a href="/vehiculo/${car.id}" data-route><h3>${escapeHtml(car.brand)} ${escapeHtml(car.model)}</h3></a><div class="catalog-specs"><span>▧ ${car.year}</span><span>◉ ${Number(car.mileage).toLocaleString("es-EC")}km</span><span>◎ ${escapeHtml(car.drive)}</span><span>♨ ${escapeHtml(car.transmission)}</span><span>▣ ${escapeHtml(car.fuel)}</span></div><div class="catalog-price"><div><small>Precio ${car.condition==="nuevos"?"actual":"desde"}:</small><strong>${money(car.price)}</strong></div><div><small>Cuotas desde</small><strong>${money(car.monthly)}/m <i>i</i></strong></div></div><span class="guaranteed-label ${guaranteed?"":"placeholder"}" ${guaranteed?"":"aria-hidden=true"}>${guaranteed?"◉ Garantizado":"&nbsp;"}</span><div class="catalog-card-actions"><a href="/vehiculo/${car.id}" data-route>Ver detalles</a><button type="button" data-compare="${car.id}" class="${compared?"selected":""}" aria-label="${compared?"Quitar de comparación":"Agregar a comparación"}">${compared?"✓":"🚙"}</button></div></div></article>`;}

async function catalogPage(){const queryType=new URLSearchParams(location.search).get("tipo");state.catalogType=queryType==="nuevos"?"nuevos":"usados";setTitle("Carros en venta en Ecuador");const serverFilters=Object.fromEntries(Object.entries(state.filters).filter(([key,value])=>value&&!['seller','opportunity'].includes(key))),qs=new URLSearchParams({catalogType:state.catalogType,...serverFilters}),data=await request(`/api/vehicles?${qs}`);let items=data.items;if(state.selectedBrands.size)items=items.filter(car=>state.selectedBrands.has(car.brand));if(state.filters.seller)items=items.filter(car=>state.filters.seller==="1001"?car.featured:!car.featured);if(state.filters.opportunity)items=items.filter(car=>state.filters.opportunity==="bonos"?car.condition==="nuevos"||car.badge==="Nuevo":car.badge==="Oportunidad");return `<section class="catalog-heading"><div><h1>Carros en venta en Ecuador</h1><p><a href="/" data-route>Inicio</a><span>›</span>Catálogo<span>›</span></p></div><form class="catalog-main-search"><label><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="6.5"></circle><path d="m16 16 4 4"></path></svg><input name="q" value="${escapeHtml(state.filters.q)}" placeholder="Ej. Toyota RAV4 Automático Quito" aria-label="Buscar carros"></label></form></section><section class="catalog-layout"><form class="catalog-filters">${filtersMarkup()}</form><div class="catalog-results">${partnerExplorer(true)}<div class="catalog-toolbar"><p><b>${items.length}</b> resultados</p><label class="catalog-sort"><span>☷ &nbsp; Ordenar por</span><select id="catalog-sort"><option value="" ${!state.filters.sort?"selected":""}>Destacados</option><option value="price-asc" ${state.filters.sort==="price-asc"?"selected":""}>Menor precio</option><option value="price-desc" ${state.filters.sort==="price-desc"?"selected":""}>Mayor precio</option><option value="year-desc" ${state.filters.sort==="year-desc"?"selected":""}>Más recientes</option><option value="mileage-asc" ${state.filters.sort==="mileage-asc"?"selected":""}>Menor kilometraje</option></select></label></div>${items.length?`<div class="catalog-cards">${items.map(catalogCarCard).join("")}</div>`:`<div class="empty-state"><span>⌕</span><h3>Búsqueda sin resultados</h3><p>Prueba con menos filtros o cambia el tipo de inventario.</p><button class="secondary-button" data-clear-filters>Limpiar búsqueda</button></div>`}</div></section>`;}

function whatsappLink(car){const text=encodeURIComponent(`Hola, quiero información sobre el ${car.brand} ${car.model} (${car.code}).`);return `https://wa.me/?text=${text}`;}

function similarDetailCard(car){const previous=Math.round(car.price*1.08/100)*100;return `<article class="similar-detail-card">
  <a class="similar-detail-image" href="/vehiculo/${car.id}" data-route><img src="${escapeHtml(car.image)}" alt="${escapeHtml(car.brand)} ${escapeHtml(car.model)}" loading="lazy">${car.featured?'<span>BONOS ESPECIALES</span>':""}</a>
  <div class="similar-detail-body"><a href="/vehiculo/${car.id}" data-route><h3>${escapeHtml(car.brand)} ${escapeHtml(car.model)}</h3></a><div class="similar-detail-price"><span><del>${money(previous)}</del><small>Precio anterior:</small></span><strong>${money(car.price)}<small>Precio actual:</small></strong></div><div class="similar-detail-specs"><span>▧ ${car.year}</span><span>◉ ${Number(car.mileage).toLocaleString("es-EC")} km</span><span>◎ ${escapeHtml(car.drive)}</span><span>♨ ${escapeHtml(car.transmission)}</span><span>▣ ${escapeHtml(car.fuel)}</span></div><a class="similar-detail-more" href="/vehiculo/${car.id}" data-route>Ver más</a></div></article>`;}

function vehicleCarousel(car){const views=["center center","62% center","40% center","center 38%","center 63%","70% 55%","28% 54%","center center"],label=`${car.brand} ${car.model}`;return `<section class="vehicle-carousel" aria-label="Galería de fotos de ${escapeHtml(label)}" tabindex="0"><div class="vehicle-carousel-viewport">${views.map((position,index)=>`<figure class="vehicle-carousel-slide ${index===0?"is-active":""}" data-gallery-slide="${index}" ${index===0?"":"hidden"}><img src="${escapeHtml(car.image)}" alt="${index===0?`Vista principal del ${escapeHtml(label)}`:`Vista ${index+1} del ${escapeHtml(label)}`}" style="object-position:${position}"></figure>`).join("")}<button type="button" class="vehicle-carousel-arrow previous" data-gallery-move="-1" aria-label="Foto anterior">‹</button><button type="button" class="vehicle-carousel-arrow next" data-gallery-move="1" aria-label="Foto siguiente">›</button><div class="vehicle-carousel-bottom"><div class="vehicle-carousel-dots" role="tablist" aria-label="Seleccionar foto">${views.map((_,index)=>`<button type="button" data-gallery-dot="${index}" role="tab" aria-label="Ver foto ${index+1}" aria-selected="${index===0}"></button>`).join("")}</div><output class="vehicle-carousel-count" aria-live="polite">1/${views.length}</output></div></div></section>`;}
function updateVehicleCarousel(index){const carousel=document.querySelector(".vehicle-carousel");if(!carousel)return;const slides=[...carousel.querySelectorAll("[data-gallery-slide]")],total=slides.length,next=(index+total)%total;slides.forEach((slide,current)=>{const active=current===next;slide.classList.toggle("is-active",active);slide.hidden=!active;});carousel.querySelectorAll("[data-gallery-dot]").forEach((dot,current)=>dot.setAttribute("aria-selected",String(current===next)));carousel.querySelector(".vehicle-carousel-count").textContent=`${next+1}/${total}`;}

async function detailPage(id){const {item:car}=await request(`/api/vehicles/${id}`);setTitle(`${car.brand} ${car.model}`);const previous=Math.round(car.price*1.06/100)*100,entry=Math.round(car.price*.25),similar=[...state.vehicles.filter(item=>item.id!==car.id&&item.category===car.category),...state.vehicles.filter(item=>item.id!==car.id&&item.category!==car.category)].slice(0,5),wa=whatsappLink(car),favorite=state.localFavorites.has(car.id);return `<section class="vehicle-detail-page">
  <nav class="detail-breadcrumbs" aria-label="Migas de pan"><a href="/" data-route>Inicio</a><span>›</span><a href="/catalogo${car.condition==="nuevos"?"?tipo=nuevos":""}" data-route>Catálogo</a><span>›</span><span>${escapeHtml(car.brand)}</span><span>›</span><span>${escapeHtml(car.model.split(" ")[0])}</span><span>›</span><strong>${escapeHtml(`${car.brand} ${car.model}`)}</strong></nav>
  <div class="detail-main-layout"><div class="detail-content-column">
    ${vehicleCarousel(car)}
    <section class="vehicle-facts"><h2>Detalles</h2><div class="facts-row">${[[car.year,"Año"],[car.code,"Placa"],[Number(car.mileage).toLocaleString("es-EC"),"Kilometraje"]].map(([value,label])=>`<div><strong>${escapeHtml(value)}</strong><span>${label}</span></div>`).join("")}</div></section>
    <section class="vehicle-characteristics"><h2>Características del carro</h2><div class="characteristics-grid">${[[car.transmission,"Transmisión"],["Hidráulica","Dirección"],[car.engine,"Motor"],[car.drive,"Tracción"],[car.color,"Color"],[car.upholstery,"Tapizado"],[car.fuel,"Combustible"],["Eléctricos","Vidrios"],[car.origin,"País de origen"]].map(([value,label])=>`<div><strong>${escapeHtml(value)}</strong><span>${label}</span></div>`).join("")}</div></section>
    <section class="test-drive-panel"><h2>¿Estás listo para tu seminuevo?</h2><button type="button" data-test-drive="${car.id}"><span>◉</span> Test drive</button></section>
    <section class="detail-benefits"><h2>Beneficios de comprar tu carro en 1001carros.com</h2><div>${["Financiamiento","Sin intermediarios","Test de Manejo","Resérvalo con $500"].map(label=>`<span><b>✓</b>${label}</span>`).join("")}</div></section>
  </div><aside class="detail-side-column">
    <div class="vehicle-heading"><p>${escapeHtml(car.brand)}</p><h1>${escapeHtml(car.model)}</h1><span>${car.year} | ${Number(car.mileage).toLocaleString("es-EC")} KM | ${escapeHtml(car.transmission)}</span></div>
    <div class="detail-bonus">${car.featured||car.condition==="nuevos"?"BONOS ESPECIALES":"GARANTÍA MECÁNICA"}</div>
    <section class="price-card"><header><strong>Detalles del precio</strong><b>$</b></header><div class="price-card-total"><span>Precio carro:</span><div><del>${money(previous)}</del><strong>${money(car.price)}</strong></div></div>${["Alistamiento","Garantía mecánica de 1 año o 20,000 km","Garantía legal y de procedencia","Garantía de satisfacción"].map(label=>`<p><b>✓</b>${label}</p>`).join("")}</section>
    ${car.agency?`<section class="detail-location-card"><h2>Ubicación</h2><strong>${escapeHtml(car.agency.name)}</strong><dl><div><dt>Dirección</dt><dd>${escapeHtml(car.agency.address)}</dd></div><div><dt>Ciudad</dt><dd>${escapeHtml(car.agency.city)}</dd></div><div><dt>Horario</dt><dd>${escapeHtml(car.agency.hours)}</dd></div><div><dt>Teléfono</dt><dd>${escapeHtml(car.agency.phone)}</dd></div></dl><a class="detail-location-link" href="/agencias?sucursal=${encodeURIComponent(car.agency.name)}" data-route>Ver detalle de la sucursal</a>${car.agency.lat!=null&&car.agency.lng!=null?`<a href="https://www.google.com/maps?q=${encodeURIComponent(car.agency.lat)},${encodeURIComponent(car.agency.lng)}" target="_blank" rel="noopener">Ver en el mapa</a>`:""}</section>`:""}
    <section class="detail-finance-card" data-detail-price="${car.price}"><h2>Financiamiento</h2><label>Entrada <small>25% del valor del carro</small><input id="detail-down-payment" type="number" min="0" max="${car.price-1000}" value="${entry}"></label><span>Selecciona un plazo</span><div class="term-options">${[12,24,36,48,60].map(term=>`<button type="button" data-detail-term="${term}" class="${term===60?"active":""}">${term} meses</button>`).join("")}</div><div class="detail-finance-result"><span>Cuota referencial</span><strong id="detail-monthly-result">${money(Math.round(((car.price-entry)*1.095)/60))}/m</strong></div><button class="detail-calculate" type="button" data-detail-calculate>Calcular</button></section>
    <section class="detail-contact-card"><h2>¿Te interesa este carro?</h2><button type="button" data-reserve-start="${car.id}">Empezar ahora <span>→</span></button></section>
    <section class="satisfaction-card"><div class="satisfaction-seal"><span>☆</span></div><h2>Garantía de Satisfacción</h2><p>Enamórate de tu seminuevo en 7 días o 300km o te devolvemos tu dinero.</p><div aria-label="Cinco estrellas">★ ★ ★ ★ ★</div></section>
  </aside></div>
  <section class="similar-vehicles"><h2>Conoce otros carros ${escapeHtml(car.category)} similares</h2><div class="similar-detail-track">${similar.map(similarDetailCard).join("")}</div></section>
  <div class="vehicle-sticky-bar"><div><strong>${escapeHtml(car.model)}</strong><span>${car.year} | ${Number(car.mileage).toLocaleString("es-EC")} KM | ${escapeHtml(car.transmission)}</span></div><strong>${money(car.price)}</strong><button type="button" class="sticky-reserve" data-reserve-start="${car.id}">Empezar ahora <span>→</span></button><button type="button" data-favorite="${car.id}" aria-label="${favorite?"Quitar de":"Guardar en"} favoritos">${favorite?"♥":"♡"}</button></div>
  </section>`;}

function sellProgress(){return `<div class="sell-progress"><h1>¡Vende en pocos pasos tu carro!</h1><div class="sell-progress-line ${state.sellStep===2?"complete":""}"><i></i><i></i></div><div><span>Registra tu auto</span><span>Tus datos</span></div></div>`;}

function sellPromo(){return `<aside class="sell-cash-promo" aria-label="Pagamos cash por tu carro"><img class="sell-promo-logo" src="https://admin.changanecuador.com/uploads/1001carros_logo_df05660ab3.svg" alt="1001Carros.com"><h2>Pagamos <span>CASH</span><br>por tu carro</h2><img class="sell-promo-art" src="/assets/vender-carros-llaves.png" alt="Dos vehículos junto a las llaves de un carro"></aside>`;}

function sellPage(){setTitle("Vender mi carro");const d=state.sellDraft,years=Array.from({length:47},(_,index)=>2026-index);return `<section class="sell-flow-page"><div class="sell-flow-main">${sellProgress()}${state.sellStep===1?`<div class="sell-step-meta"><span>Paso 1 de 2</span></div><form class="sell-step-form sell-car-form"><h2>Información de tu carro</h2><label>* Número de placa<input name="plate" required maxlength="8" value="${escapeHtml(d.plate||"")}" placeholder="ABC0000" autocomplete="off"></label><label>* Año<select name="year" required><option value="">-- Seleccionar año -</option>${years.map(year=>`<option value="${year}" ${String(d.year)===String(year)?"selected":""}>${year}</option>`).join("")}</select></label><label>* Marca<input name="brand" required value="${escapeHtml(d.brand||"")}" placeholder="Marca" autocomplete="off"></label><label>* Modelo<input name="model" required value="${escapeHtml(d.model||"")}" placeholder="Modelo" autocomplete="off"></label><label>* Kilometraje<input name="mileage" type="number" min="0" required value="${escapeHtml(d.mileage||"")}" placeholder="000000"></label><label>* Color<input name="color" required value="${escapeHtml(d.color||"")}" placeholder="Color"></label><label class="sell-trade-toggle"><span>Quiero cambiar mi carro por un seminuevo de 1001Carros.com</span><input name="tradeIn" type="checkbox" ${d.tradeIn?"checked":""}><i></i></label><button class="sell-flow-submit" type="submit" disabled>Continuar</button></form>`:`<div class="sell-step-meta"><button type="button" data-sell-back>‹&nbsp; Atrás</button><span>Paso 2 de 2</span></div><form class="sell-step-form sell-contact-form"><h2>Tus datos</h2><p>Llena la siguiente información:</p><label>* Nombres<input name="firstName" required value="${escapeHtml(d.firstName||"")}" placeholder="Nombres" autocomplete="given-name"></label><label>* Apellidos<input name="lastName" required value="${escapeHtml(d.lastName||"")}" placeholder="Apellidos" autocomplete="family-name"></label><label>* Correo<div class="sell-input-icon"><span>✉</span><input name="email" type="email" required value="${escapeHtml(d.email||"")}" placeholder="correo" autocomplete="email"></div></label><label>* Celular<input name="phone" type="tel" required value="${escapeHtml(d.phone||"")}" placeholder="Celular" autocomplete="tel"></label><label class="sell-consent"><input name="terms" type="checkbox" required ${d.terms?"checked":""}><span>He leído y estoy de acuerdo con los <a href="#terminos">términos y condiciones</a> y <a href="#privacidad">políticas de privacidad</a></span></label><label class="sell-recaptcha"><input name="human" type="checkbox" required><i></i><span>No soy un robot</span><b>↻<small>reCAPTCHA</small></b></label><button class="sell-flow-submit" type="submit" disabled>Finalizar</button><p class="form-message" role="status"></p></form>`}</div>${sellPromo()}</section>`;}

function financePage(){setTitle("Financiamiento");const initial=new URLSearchParams(location.search).get("price")||24000;return `<section class="page-hero finance-hero"><div><p class="eyebrow">Financiamiento</p><h1>Tu próximo carro,<br>una cuota a tu medida.</h1><p>Simula una referencia y deja tus datos para recibir opciones reales.</p></div></section><section class="finance-page"><div class="calculator large"><div class="calculator-value"><span>Cuota referencial</span><strong id="monthly-value">$0</strong><small>/ mes</small></div><label>Precio del carro <output id="price-output"></output><input id="price-range" type="range" min="10000" max="80000" step="1000" value="${initial}"></label><label>Entrada <output id="down-output"></output><input id="down-range" type="range" min="0" max="30000" step="500" value="6000"></label><label>Plazo <output id="term-output">60 meses</output><input id="term-range" type="range" min="12" max="72" step="12" value="60"></label><p>*Simulación referencial. La aprobación, entrada y tasa dependen de la entidad financiera.</p></div><form class="lead-form finance-lead"><p class="eyebrow blue">Recibe asesoría</p><h2>Te ayudamos a encontrar una opción.</h2><label>Nombre<input name="name" required></label><label>Celular<input name="phone" type="tel" required></label><label>Correo<input name="email" type="email"></label><button class="primary-button">Quiero que me contacten</button><p class="form-message"></p></form></section>`;}

async function agenciesPage(){setTitle("Agencias");const {items}=await request("/api/agencies"),selectedName=new URLSearchParams(location.search).get("sucursal");return `<section class="page-hero agency-hero"><div><p class="eyebrow">Estamos cerca</p><h1>Encuentra tu agencia.</h1><p>Visita nuestro stock y prueba el carro que te gusta.</p></div></section><section class="agency-section"><div class="section-heading"><div><p class="eyebrow blue">Red nacional</p><h2>Agencias 1001Carros.com</h2></div><label class="sort-control">Filtrar ciudad <select id="agency-city"><option value="">Todas</option>${[...new Set(items.map(x=>x.city))].map(x=>`<option>${x}</option>`).join("")}</select></label></div><div class="agency-grid">${[...items].sort((a,b)=>(b.name===selectedName)-(a.name===selectedName)).map(x=>`<article class="agency-card${x.name===selectedName?" is-selected":""}" data-agency-city="${x.city}">${x.name===selectedName?'<strong class="agency-selected-badge">Tu carro está en esta sucursal</strong>':""}<div class="agency-map"><span>⌖</span><small>${x.lat.toFixed(3)}, ${x.lng.toFixed(3)}</small></div><div><p>${escapeHtml(x.city)}</p><h3>${escapeHtml(x.name)}</h3><address>${escapeHtml(x.address)}</address><span>${escapeHtml(x.hours)}</span><a href="tel:${x.phone.replace(/\D/g,"")}">${escapeHtml(x.phone)} →</a></div></article>`).join("")}</div></section>`;}

function accountPage(){return `<section class="account-page"><div class="account-card"><span class="account-avatar">${escapeHtml(state.session.user.name[0])}</span><p class="eyebrow blue">Mi cuenta</p><h1>Hola, ${escapeHtml(state.session.user.name)}</h1><p>${escapeHtml(state.session.user.email)}</p><div class="account-links"><a href="/favoritos" data-route>Ver mis favoritos <span>→</span></a><a href="/catalogo" data-route>Explorar catálogo <span>→</span></a></div><button class="secondary-outline" id="logout">Cerrar sesión</button></div></section>`;}

function authShell(content){return `<section class="auth-page"><div class="auth-backdrop" aria-hidden="true"><span>Compra con respaldo.</span><strong>Tu próximo carro<br>empieza aquí.</strong><p>Guarda tus favoritos y retoma tu búsqueda cuando quieras.</p></div><div class="auth-panel">${content}</div></section>`;}

function loginPage(){setTitle("Iniciar sesión");if(state.session)return accountPage();return authShell(`<div class="auth-heading"><span class="auth-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="4"></circle><path d="M4.5 20c.7-4.1 3.2-6.2 7.5-6.2s6.8 2.1 7.5 6.2"></path></svg></span><h1>Iniciar sesión</h1><p>Ingresa a tu cuenta y continúa buscando el carro ideal para ti.</p></div><a class="email-login-button" href="/login/email" data-route data-email-login><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="2"></rect><path d="m4 7 8 6 8-6"></path></svg><span>Iniciar sesión con tu correo</span><b>→</b></a><div class="auth-divider"><span>¿Aún no tienes cuenta?</span></div><a class="create-account-link" href="/login/email?mode=register" data-route>Crear una cuenta</a><p class="auth-legal">Al continuar aceptas nuestros términos y políticas de privacidad.</p>`);}

function loginEmailPage(){setTitle("Iniciar sesión con tu correo");if(state.session)return accountPage();const registering=new URLSearchParams(location.search).get("mode")==="register";return authShell(`<a class="auth-back" href="/login" data-route aria-label="Volver"><span>←</span> Volver</a><div class="auth-heading email-heading"><span class="auth-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="2"></rect><path d="m4 7 8 6 8-6"></path></svg></span><h1>${registering?"Crear una cuenta":"Iniciar sesión con tu correo"}</h1><p>${registering?"Regístrate para guardar tus carros favoritos.":"Usa el correo y la contraseña de tu cuenta."}</p></div>${registering?`<form class="auth-form" id="register-form"><label>Nombre completo<input name="name" autocomplete="name" required placeholder="Tu nombre"></label><label>Correo electrónico<input name="email" type="email" autocomplete="email" required placeholder="nombre@correo.com"></label><label>Contraseña<input name="password" type="password" autocomplete="new-password" minlength="6" required placeholder="Mínimo 6 caracteres"></label><button class="primary-button">Crear mi cuenta</button><p class="form-message" role="alert"></p></form><p class="auth-switch">¿Ya tienes una cuenta? <a href="/login/email" data-route>Inicia sesión</a></p>`:`<form class="auth-form" id="login-form"><label>Correo electrónico<input name="email" type="email" autocomplete="email" required placeholder="nombre@correo.com"></label><label>Contraseña<input name="password" type="password" autocomplete="current-password" required placeholder="Ingresa tu contraseña"></label><button class="primary-button">Iniciar sesión</button><p class="form-message" role="alert"></p></form><p class="auth-switch">¿No tienes una cuenta? <a href="/login/email?mode=register" data-route>Créala aquí</a></p>`}`);}

async function favoritesPage(){setTitle("Favoritos");let items=state.vehicles.filter(x=>state.localFavorites.has(x.id));if(state.session)try{items=(await request("/api/favorites")).items}catch{}return `<section class="page-hero compact"><div><p class="eyebrow">Tu selección</p><h1>Carros favoritos</h1><p>Compara con calma y vuelve cuando quieras.</p></div></section><section class="catalog-section">${items.length?`<div class="car-grid">${items.map(carCard).join("")}</div>`:`<div class="empty-state"><span>♡</span><h3>Aún no guardaste carros</h3><p>Usa el corazón del catálogo para armar tu selección.</p><a class="secondary-button" href="/catalogo" data-route>Explorar catálogo</a></div>`}</section>`;}
function contactPage(){setTitle("Contacto");return `<section class="contact-page"><div><p class="eyebrow">Hablemos</p><h1>¿Cómo podemos ayudarte?</h1><p>Déjanos un mensaje. La solicitud quedará guardada para que un asesor la atienda.</p><div class="contact-data"><span><b>Ventas</b> 1800-1001-00</span><span><b>WhatsApp</b> 099 100 1001</span><span><b>Horario</b> Lun–Sáb 09:00–18:00</span></div></div><form class="lead-form contact-lead"><label>Nombre<input name="name" required></label><label>Correo<input name="email" type="email" required></label><label>Celular<input name="phone" type="tel"></label><label>Mensaje<textarea name="message" rows="5" required></textarea></label><button class="yellow-button">Enviar mensaje</button><p class="form-message"></p></form></section>`;}

function reservationAgencyCard(agency,{selected=false,transfer=false}={}){return `<button type="button" class="reservation-agency-card ${selected?"selected":""}" ${transfer?"data-open-agency-picker":"data-reservation-agency=\""+agency.id+"\""}>
  <span class="reservation-agency-icon" aria-hidden="true">${transfer?"↗":"⌂"}</span><span class="reservation-agency-copy"><strong>${transfer?"Enviar a otra agencia":escapeHtml(agency.name)}</strong><small>${transfer?"Realiza tu test drive en otro punto 1001Carros.com":`${escapeHtml(agency.address)} · ${escapeHtml(agency.city)}`}</small>${selected?"<em>Agencia seleccionada</em>":""}</span><b aria-hidden="true">${transfer?"→":"✓"}</b></button>`;}
function agencyPickerRows(query=state.reservation.originQuery){const ordered=agenciesByDistance(query),needle=normalized(query),matches=ordered.filter(agency=>!needle||normalized(`${agency.name} ${agency.address} ${agency.city}`).includes(needle)||reservationOrigins.some(origin=>origin.terms.some(term=>needle.includes(normalized(term)))));const visible=matches.length?matches:ordered;return visible.map((agency,index)=>`<article class="agency-picker-row ${agency.id===state.reservation.selectedAgencyId?"selected":""}"><div><strong>${escapeHtml(agency.name)}</strong><span>${index===0?"Más cercana · ":""}${agency.distance<10?`${agency.distance.toFixed(1)} km`:`${Math.round(agency.distance)} km`}</span><address>${escapeHtml(agency.address)}<br>${escapeHtml(agency.city)}</address><small>${escapeHtml(agency.hours)}</small></div>${agency.id===state.reservation.selectedAgencyId?"<em>Seleccionada</em>":`<button type="button" data-reservation-agency="${agency.id}">Elegir</button>`}</article>`).join("")||"<p class=\"agency-picker-empty\">No encontramos una agencia con esa búsqueda.</p>";}
function openAgencyPicker(){const modal=document.querySelector("#modal");modal.hidden=false;modal.innerHTML=`<section class="agency-picker-modal" role="dialog" aria-modal="true" aria-labelledby="agency-picker-title"><header><div><h2 id="agency-picker-title">Elige una agencia</h2><p>Ordenadas desde tu ubicación consultada.</p></div><button type="button" class="modal-close" aria-label="Cerrar">×</button></header><label class="agency-picker-search"><span aria-hidden="true">⌕</span><input id="agency-picker-search" value="${escapeHtml(state.reservation.originQuery)}" placeholder="Ej. Norte de Quito, Cumbayá o Sur de Quito" autocomplete="off"></label><p class="agency-picker-hint" id="agency-picker-hint">Ubicación de referencia: <strong>${escapeHtml(reservationOrigin(state.reservation.originQuery).label)}</strong></p><div class="agency-picker-list" id="agency-picker-list">${agencyPickerRows()}</div></section>`;document.querySelector("#agency-picker-search")?.focus();}
function updateAgencyPicker(query){state.reservation.originQuery=query||"Cumbayá, Quito";const hint=document.querySelector("#agency-picker-hint"),list=document.querySelector("#agency-picker-list");if(hint)hint.innerHTML=`Ubicación de referencia: <strong>${escapeHtml(reservationOrigin(state.reservation.originQuery).label)}</strong>`;if(list)list.innerHTML=agencyPickerRows(state.reservation.originQuery);}
async function reservationPage(id){setTitle("Agenda tu test drive");const {item:car}=await request(`/api/vehicles/${id}`);if(!state.agencies.length)state.agencies=(await request("/api/agencies")).items;const defaultAgency=state.agencies.find(agency=>agency.name===car.agency?.name)||state.agencies.find(agency=>normalized(agency.name).includes("cumbaya"))||state.agencies[0];if(state.reservation.vehicleId!==car.id){state.reservation.vehicleId=car.id;state.reservation.selectedAgencyId=null;}if(!state.reservation.selectedAgencyId||!state.agencies.some(agency=>agency.id===state.reservation.selectedAgencyId))state.reservation.selectedAgencyId=defaultAgency?.id||null;const selected=state.agencies.find(agency=>agency.id===state.reservation.selectedAgencyId)||defaultAgency;return `<section class="reservation-page"><aside class="reservation-summary"><p>Completa tu reserva</p><article><img src="${escapeHtml(car.image)}" alt="${escapeHtml(`${car.brand} ${car.model}`)}"><div><strong>${escapeHtml(`${car.year} ${car.brand} ${car.model}`)}</strong><span>${money(car.price)} · ${Number(car.mileage).toLocaleString("es-EC")} km</span></div></article><ol><li class="active"><i>1</i><span>Ubicación</span></li><li><i>2</i><span>Datos de contacto</span></li><li><i>3</i><span>Agenda tu visita</span></li><li><i>4</i><span>Confirmación</span></li></ol></aside><main class="reservation-main"><div class="reservation-content"><p class="eyebrow blue">Test drive sin compromiso</p><h1>Elige dónde hacer tu test drive</h1><p class="reservation-intro">Selecciona una agencia. Si eliges otra ciudad, coordinamos el traslado del vehículo antes de tu visita.</p><label class="reservation-origin"><span aria-hidden="true">⌖</span><input id="reservation-origin" value="${escapeHtml(state.reservation.originQuery)}" list="reservation-origins" aria-label="Ubicación desde donde consultas"><datalist id="reservation-origins"><option value="Cumbayá, Quito"><option value="Norte de Quito"><option value="Sur de Quito"><option value="Quito"></datalist></label>${selected?reservationAgencyCard(selected,{selected:true}):""}<div class="reservation-or"><span></span>o<span></span></div>${reservationAgencyCard({}, {transfer:true})}<p class="reservation-guarantee"><b>✓</b> Coordinaremos tu visita y el traslado del carro si es necesario.</p><div class="reservation-actions"><button type="button" class="reservation-back" data-reservation-back>Volver</button><button type="button" class="reservation-confirm" data-reservation-confirm="${car.id}">Seleccionar y continuar</button></div></div></main></section>`;}

async function renderRoute(){app.innerHTML='<div class="page-loader"><span></span><p>Cargando…</p></div>';window.scrollTo(0,0);try{let path=location.pathname;if(!state.vehicles.length)state.vehicles=(await request("/api/vehicles")).items;if(path==="/"&&!state.brands.length)state.brands=(await request(`/api/brands?condition=${state.brandCondition}`)).items;if(["/seminuevos","/usados","/nuevos"].includes(path)){state.catalogType=path==="/nuevos"?"nuevos":"usados";const target=`/catalogo${state.catalogType==="nuevos"?"?tipo=nuevos":""}`;history.replaceState({},"",target);path="/catalogo";}let html;if(path==="/")html=homePage();else if(path==="/catalogo")html=await catalogPage();else if(/^\/vehiculo\/\d+$/.test(path))html=await detailPage(Number(path.split("/").pop()));else if(/^\/reservar\/\d+$/.test(path))html=await reservationPage(Number(path.split("/").pop()));else if(path.startsWith("/seminuevo/")){const code=decodeURIComponent(path.split("/").pop()).toLowerCase(),car=state.vehicles.find(item=>item.code.toLowerCase()===code);html=car?await detailPage(car.id):'<div class="not-found"><b>404</b><h1>No encontramos este vehículo.</h1><a href="/catalogo" data-route>Volver al catálogo →</a></div>';}else if(path==="/vender")html=sellPage();else if(path==="/financiamiento")html=financePage();else if(path==="/agencias")html=await agenciesPage();else if(path==="/login")html=loginPage();else if(path==="/login/email")html=loginEmailPage();else if(path==="/favoritos")html=await favoritesPage();else if(path==="/contacto")html=contactPage();else{setTitle("Página no encontrada");html='<div class="not-found"><b>404</b><h1>Esta ruta no llegó al destino.</h1><a href="/" data-route>Volver al inicio →</a></div>';}app.innerHTML=html;app.focus({preventScroll:true});afterRender();}catch(error){app.innerHTML=`<div class="not-found"><b>!</b><h1>No pudimos cargar esta página.</h1><p>${escapeHtml(error.message)}</p><button class="secondary-button" onclick="location.reload()">Intentar de nuevo</button></div>`;}}

function afterRender(){if(document.querySelector("#price-range"))updateCalculator();document.querySelector("#catalog-sort")?.setAttribute("value",state.filters.sort);document.querySelector("#account-link .account-name").textContent=state.session?state.session.user.name.split(" ")[0]:"Iniciar sesión";updateDetailStickyBar();updateSellButton();}
function updateDetailStickyBar(){document.querySelector(".vehicle-sticky-bar")?.classList.toggle("visible",window.scrollY>560);}
function updateDetailFinancing(){const card=document.querySelector(".detail-finance-card");if(!card)return;const price=Number(card.dataset.detailPrice),down=Math.min(Math.max(Number(document.querySelector("#detail-down-payment")?.value||0),0),price-1000),term=Number(card.querySelector("[data-detail-term].active")?.dataset.detailTerm||60),monthly=Math.round(((price-down)*1.095)/term);document.querySelector("#detail-monthly-result").textContent=`${money(monthly)}/m`;}
function updateSellButton(){const form=document.querySelector(".sell-step-form"),button=form?.querySelector(".sell-flow-submit");if(button)button.disabled=!form.checkValidity();}
function updateCalculator(){const price=Number(document.querySelector("#price-range")?.value||24000),down=Math.min(Number(document.querySelector("#down-range")?.value||0),price-1000),term=Number(document.querySelector("#term-range")?.value||60),monthly=Math.round(((price-down)*1.095)/term);document.querySelector("#price-output").textContent=money(price);document.querySelector("#down-output").textContent=money(down);document.querySelector("#term-output").textContent=`${term} meses`;document.querySelector("#monthly-value").textContent=money(monthly);}
function updateCompare(){const bar=document.querySelector("#compare-bar");bar.hidden=!state.compare.size;document.querySelector("#compare-count").textContent=`${state.compare.size} de 3 seleccionados`;document.querySelector("#compare-thumbs").innerHTML=[...state.compare].map(id=>{const car=state.vehicles.find(x=>x.id===id);return `<img src="${car.image}" alt="${escapeHtml(car.model)}">`;}).join("");}
function openLeadModal(vehicleId){const car=state.vehicles.find(x=>x.id===vehicleId),modal=document.querySelector("#modal");modal.hidden=false;modal.innerHTML=`<div class="modal-card"><button class="modal-close" aria-label="Cerrar">×</button><p class="eyebrow blue">${escapeHtml(car.brand)}</p><h2>${escapeHtml(car.model)}</h2><p>Déjanos tu contacto para agendar un test drive o resolver tus preguntas.</p><form class="lead-form vehicle-lead"><input type="hidden" name="vehicleId" value="${car.id}"><label>Nombre<input name="name" required></label><label>Celular<input name="phone" required></label><label>Mensaje<textarea name="message" rows="3">Quiero información y un test drive.</textarea></label><button class="primary-button">Contactar un asesor</button><p class="form-message"></p></form></div>`;}
function openReserveModal(vehicleId){const car=state.vehicles.find(item=>item.id===vehicleId),modal=document.querySelector("#modal"),name=`${car.brand} ${car.model}`;modal.hidden=false;modal.innerHTML=`<section class="reserve-modal" role="dialog" aria-modal="true" aria-labelledby="reserve-title"><header><strong>Así funciona</strong><button type="button" class="modal-close" aria-label="Cerrar">×</button></header><div class="reserve-modal-image"><img src="${escapeHtml(car.image)}" alt="${escapeHtml(name)}"><span aria-hidden="true">⌑</span></div><div class="reserve-modal-copy"><h2 id="reserve-title">Reserva este ${escapeHtml(name)}</h2><p>Te ayudamos a planificar el siguiente paso.</p><ul><li><b>⌖</b><span><strong>Visita una agencia cerca de ti</strong><small>Elige el punto de atención que te resulte más cómodo.</small></span></li><li><b>↗</b><span><strong>¿Prefieres que te contactemos?</strong><small>Un asesor te guía con opciones claras y sin compromiso.</small></span></li><li><b>◉</b><span><strong>Prueba el carro antes de decidir</strong><small>Conoce el vehículo y resuelve tus dudas en persona.</small></span></li></ul><button type="button" class="reserve-continue" data-reserve-continue="${car.id}">Continuar</button></div></section>`;}
function openTestDriveModal(vehicleId){const car=state.vehicles.find(item=>item.id===vehicleId),modal=document.querySelector("#modal"),name=`${car.brand} ${car.model}`;modal.hidden=false;modal.innerHTML=`<section class="test-drive-modal" role="dialog" aria-modal="true" aria-labelledby="test-drive-title"><header><strong>Tu test drive</strong><button type="button" class="modal-close" aria-label="Cerrar">×</button></header><div class="test-drive-icon" aria-hidden="true">🚙</div><div class="test-drive-copy"><h2 id="test-drive-title">Prueba el ${escapeHtml(name)} donde prefieras</h2><p>Elige la agencia 1001Carros.com que te quede mejor. Nosotros nos encargamos de llevar el carro para que puedas realizar tu test drive.</p><div><span>⌖</span><p><strong>Disponible en cualquier agencia</strong><small>Coordinamos el traslado del vehículo antes de tu visita.</small></p></div><button type="button" data-test-drive-continue="${car.id}">Quiero agendar mi test drive</button></div></section>`;}
function openBrandModal(){const modal=document.querySelector("#modal"),cars=state.vehicles.filter(car=>state.catalogType==="nuevos"?car.condition==="nuevos":car.condition!=="nuevos"),brands=[...new Set(cars.map(car=>car.brand))].sort((a,b)=>a.localeCompare(b,"es"));modal.hidden=false;modal.innerHTML=`<section class="brand-picker-modal" role="dialog" aria-modal="true" aria-labelledby="brand-picker-title"><header><h2 id="brand-picker-title">Selecciona una marca</h2><button type="button" class="modal-close" aria-label="Cerrar">×</button></header><form id="brand-selection-form"><div class="brand-picker-list">${brands.map(brand=>`<label><input type="checkbox" value="${escapeHtml(brand)}" ${state.selectedBrands.has(brand)?"checked":""}><span>${escapeHtml(brand)} <small>(${cars.filter(car=>car.brand===brand).length})</small></span></label>`).join("")}</div><footer><button type="button" data-brand-modal-done>Listo</button></footer></form></section>`;}

document.addEventListener("click",async event=>{
  const homeSearchChoice=event.target.closest("[data-home-search]");if(homeSearchChoice){const query=homeSearchChoice.dataset.homeSearch;saveRecentSearch(query);state.filters.q=query;state.catalogType="usados";return navigate("/catalogo");}
  const shopSource=event.target.closest("[data-shop-source]");if(shopSource){state.filters=emptyFilters();state.selectedBrands.clear();if(shopSource.dataset.shopSource==="1001")state.filters.seller="1001";if(shopSource.dataset.shopSource==="autosok")state.filters.seller="autosok";if(shopSource.dataset.shopSource==="changan"){state.catalogType="nuevos";state.filters.brand="Changan";}else state.catalogType="usados";return navigate(`/catalogo${state.catalogType==="nuevos"?"?tipo=nuevos":""}`);}
  if(!event.target.closest(".reference-search-wrap"))document.querySelector("#home-search-panel")?.classList.remove("is-visible");
  const reserveStart=event.target.closest("[data-reserve-start]");if(reserveStart){openReserveModal(Number(reserveStart.dataset.reserveStart));return;}
  const reserveContinue=event.target.closest("[data-reserve-continue]");if(reserveContinue){document.querySelector("#modal").hidden=true;navigate(`/reservar/${reserveContinue.dataset.reserveContinue}`);return;}
  const testDrive=event.target.closest("[data-test-drive]");if(testDrive){openTestDriveModal(Number(testDrive.dataset.testDrive));return;}
  const testDriveContinue=event.target.closest("[data-test-drive-continue]");if(testDriveContinue){document.querySelector("#modal").hidden=true;navigate(`/reservar/${testDriveContinue.dataset.testDriveContinue}`);return;}
  if(event.target.closest("[data-open-agency-picker]")){openAgencyPicker();return;}
  const reservationAgency=event.target.closest("[data-reservation-agency]");if(reservationAgency){state.reservation.selectedAgencyId=Number(reservationAgency.dataset.reservationAgency);document.querySelector("#modal").hidden=true;renderRoute();return;}
  if(event.target.closest("[data-reservation-back]")){history.back();return;}
  const reservationConfirm=event.target.closest("[data-reservation-confirm]");if(reservationConfirm){const agency=state.agencies.find(item=>item.id===state.reservation.selectedAgencyId);openLeadModal(Number(reservationConfirm.dataset.reservationConfirm));const message=document.querySelector(".vehicle-lead textarea[name=message]");if(message&&agency)message.value=`Quiero agendar un test drive en ${agency.name}.`;return;}
  if(event.target.closest("[data-brand-picker]")){openBrandModal();return;}
  if(event.target.closest("[data-brand-modal-done]")){state.selectedBrands=new Set([...document.querySelectorAll("#brand-selection-form input:checked")].map(input=>input.value));state.filters.brand="";document.querySelector("#modal").hidden=true;renderRoute();return;}
  const galleryMove=event.target.closest("[data-gallery-move]");if(galleryMove){const current=[...document.querySelectorAll("[data-gallery-slide]")].findIndex(slide=>slide.classList.contains("is-active"));updateVehicleCarousel(current+Number(galleryMove.dataset.galleryMove));return;}
  const galleryDot=event.target.closest("[data-gallery-dot]");if(galleryDot){updateVehicleCarousel(Number(galleryDot.dataset.galleryDot));return;}
  if(event.target.closest("[data-sell-back]")){state.sellStep=1;renderRoute();return;}
  const galleryToggle=event.target.closest("[data-gallery-toggle]");if(galleryToggle){const gallery=document.querySelector(".photo-board"),reopen=document.querySelector(".gallery-reopen"),closing=!gallery.hidden;gallery.hidden=closing;reopen.hidden=!closing;return;}
  const detailTerm=event.target.closest("[data-detail-term]");if(detailTerm){document.querySelectorAll("[data-detail-term]").forEach(button=>button.classList.toggle("active",button===detailTerm));updateDetailFinancing();return;}
  if(event.target.closest("[data-detail-calculate]")){updateDetailFinancing();showToast("Cuota referencial actualizada");return;}
  const showcaseTab=event.target.closest("[data-showcase-category]");if(showcaseTab){state.showcaseCategory=showcaseTab.dataset.showcaseCategory;const section=document.querySelector(".inventory-showcase");if(section)section.outerHTML=inventoryShowcase();return;}
  const showcaseScroll=event.target.closest("[data-showcase-scroll]");if(showcaseScroll){document.querySelector("#showcase-track")?.scrollBy({left:Number(showcaseScroll.dataset.showcaseScroll)*640,behavior:"smooth"});return;}
  const brandLink=event.target.closest("[data-brand-catalog]");if(brandLink){event.preventDefault();state.filters.brand=brandLink.dataset.brandCatalog;state.catalogType=state.brandCondition==="nuevos"?"nuevos":"usados";navigate(`/catalogo${state.catalogType==="nuevos"?"?tipo=nuevos":""}`);return;}
  const brandTab=event.target.closest("[data-brand-condition]");if(brandTab){state.brandCondition=brandTab.dataset.brandCondition;state.brands=(await request(`/api/brands?condition=${state.brandCondition}`)).items;renderRoute();return;}
  const brandScroll=event.target.closest("[data-brand-scroll]");if(brandScroll){document.querySelector("#brand-track")?.scrollBy({left:Number(brandScroll.dataset.brandScroll)*600,behavior:"smooth"});return;}
  const route=event.target.closest("a[data-route]");if(route){event.preventDefault();navigate(route.getAttribute("href"));document.querySelector(".main-nav").classList.remove("open");return;}
  const fav=event.target.closest("[data-favorite]");if(fav){const id=Number(fav.dataset.favorite),saving=!state.localFavorites.has(id);saving?state.localFavorites.add(id):state.localFavorites.delete(id);localStorage.setItem("1001-favorites",JSON.stringify([...state.localFavorites]));if(state.session)try{await request(`/api/favorites/${id}`,{method:saving?"POST":"DELETE"});}catch{}showToast(saving?"Vehículo guardado":"Vehículo eliminado");renderRoute();return;}
  const compare=event.target.closest("[data-compare]");if(compare){const id=Number(compare.dataset.compare);if(state.compare.has(id))state.compare.delete(id);else if(state.compare.size<3)state.compare.add(id);else return showToast("Puedes comparar hasta 3 vehículos");updateCompare();const selected=state.compare.has(id);compare.classList.toggle("selected",selected);compare.innerHTML=compare.classList.contains("showcase-compare")?`Comparar <i>${selected?"✓":""}</i>`:selected?"✓":"🚙";return;}
  const catalogType=event.target.closest("[data-catalog-type]");if(catalogType){state.catalogType=catalogType.dataset.catalogType;state.filters=emptyFilters();navigate(`/catalogo${state.catalogType==="nuevos"?"?tipo=nuevos":""}`);return;}
  const catalogFilter=event.target.closest("[data-catalog-filter]");if(catalogFilter){const key=catalogFilter.dataset.catalogFilter,value=catalogFilter.dataset.filterValue;state.filters[key]=state.filters[key]===value?"":value;renderRoute();return;}
  if(event.target.closest("[data-clear-price]")){state.filters.minPrice="";state.filters.maxPrice="";renderRoute();return;}
  if(event.target.closest("[data-clear-filters]")){state.filters=emptyFilters();state.selectedBrands.clear();renderRoute();return;}
  const homeCondition=event.target.closest("[data-home-condition]");if(homeCondition){document.querySelectorAll("[data-home-condition]").forEach(x=>x.classList.remove("active"));homeCondition.classList.add("active");document.querySelector('.home-search [name="condition"]').value=homeCondition.dataset.homeCondition;return;}
  const authTab=event.target.closest("[data-auth-tab]");if(authTab){document.querySelectorAll("[data-auth-tab]").forEach(x=>x.classList.toggle("active",x===authTab));document.querySelector("#login-form").hidden=authTab.dataset.authTab!=="login";document.querySelector("#register-form").hidden=authTab.dataset.authTab!=="register";return;}
  if(event.target.closest("#logout")){state.session=null;localStorage.removeItem("1001-session");showToast("Sesión cerrada");renderRoute();return;}
  const lead=event.target.closest("[data-lead-vehicle]");if(lead)return openLeadModal(Number(lead.dataset.leadVehicle));
  if(event.target.closest(".modal-close")||event.target.id==="modal"){document.querySelector("#modal").hidden=true;return;}
});

document.addEventListener("submit",async event=>{event.preventDefault();const form=event.target,data=Object.fromEntries(new FormData(form));
  if(form.matches(".sell-car-form")){state.sellDraft={...state.sellDraft,...data,tradeIn:form.elements.tradeIn.checked};state.sellStep=2;renderRoute();return;}
  if(form.matches(".sell-contact-form")){const message=form.querySelector(".form-message");state.sellDraft={...state.sellDraft,...data,terms:form.elements.terms.checked};try{await request("/api/leads",{method:"POST",body:JSON.stringify({kind:"sell",name:`${data.firstName} ${data.lastName}`.trim(),email:data.email,phone:data.phone,plate:state.sellDraft.plate,message:JSON.stringify({year:state.sellDraft.year,brand:state.sellDraft.brand,model:state.sellDraft.model,mileage:state.sellDraft.mileage,color:state.sellDraft.color,tradeIn:Boolean(state.sellDraft.tradeIn)})})});form.innerHTML='<div class="sell-success"><b>✓</b><h2>¡Recibimos tus datos!</h2><p>Un asesor revisará la información de tu carro y se pondrá en contacto contigo.</p><a href="/catalogo" data-route>Ver carros disponibles</a></div>';state.sellDraft={};state.sellStep=1;}catch(error){message.textContent=error.message;}return;}
  if(form.matches(".home-search")){const query=String(data.q||"").trim();if(!query)return;saveRecentSearch(query);state.filters.q=query;state.catalogType="usados";return navigate("/catalogo");}
  if(form.matches(".catalog-main-search")){state.filters.q=data.q||"";return renderRoute();}
  if(form.matches(".catalog-filters")){Object.assign(state.filters,data);return renderRoute();}
  if(form.matches(".sell-lead,.finance-lead,.contact-lead,.vehicle-lead")){const kind=form.matches(".sell-lead")?"sell":form.matches(".finance-lead")?"finance":form.matches(".vehicle-lead")?"vehicle":"contact";const message=form.querySelector(".form-message");try{await request("/api/leads",{method:"POST",body:JSON.stringify({...data,kind,vehicleId:data.vehicleId?Number(data.vehicleId):null})});message.textContent="Listo. Guardamos tu solicitud y un asesor continuará el proceso.";form.reset();}catch(error){message.textContent=error.message;}return;}
  if(form.id==="login-form"||form.id==="register-form"){const message=form.querySelector(".form-message");try{const result=await request(`/api/auth/${form.id==="login-form"?"login":"register"}`,{method:"POST",body:JSON.stringify(data)});state.session=result;localStorage.setItem("1001-session",JSON.stringify(result));showToast("Sesión iniciada");navigate("/favoritos");}catch(error){message.textContent=error.message;}return;}
});
document.addEventListener("change",event=>{if(event.target.closest(".sell-step-form"))updateSellButton();if(event.target.id==="catalog-sort"){state.filters.sort=event.target.value;renderRoute();return;}if(event.target.matches(".catalog-filters select,.catalog-filters input[type=number]")){state.filters[event.target.name]=event.target.value;renderRoute();return;}if(event.target.matches("[data-range-key]")){state.filters[event.target.dataset.rangeKey]=event.target.value;renderRoute();return;}if(event.target.id==="agency-city")document.querySelectorAll(".agency-card").forEach(card=>card.hidden=event.target.value&&card.dataset.agencyCity!==event.target.value);});
document.addEventListener("input",event=>{if(event.target.matches(".home-search input[name=q]")){event.target.setAttribute("aria-expanded","true");updateHomeSearchPanel(event.target);return;}if(event.target.id==="agency-picker-search"){updateAgencyPicker(event.target.value);return;}if(event.target.id==="reservation-origin"){state.reservation.originQuery=event.target.value||"Cumbayá, Quito";return;}if(event.target.closest(".sell-step-form"))updateSellButton();if(["price-range","down-range","term-range"].includes(event.target.id))updateCalculator();if(event.target.id==="detail-down-payment")updateDetailFinancing();if(event.target.matches("[data-range-key]")){const input=document.querySelector(`[name="${event.target.dataset.rangeKey}"]`);if(input)input.value=event.target.value;}});
document.addEventListener("focusin",event=>{if(event.target.matches(".home-search input[name=q]")){event.target.setAttribute("aria-expanded","true");updateHomeSearchPanel(event.target);}});
document.addEventListener("keydown",event=>{if(event.key==="Escape"&&event.target.matches(".home-search input[name=q]")){event.target.setAttribute("aria-expanded","false");event.target.blur();}if(event.target.closest(".vehicle-carousel")&&["ArrowLeft","ArrowRight"].includes(event.key)){event.preventDefault();const current=[...document.querySelectorAll("[data-gallery-slide]")].findIndex(slide=>slide.classList.contains("is-active"));updateVehicleCarousel(current+(event.key==="ArrowRight"?1:-1));}});
document.addEventListener("pointerdown",event=>{const carousel=event.target.closest(".vehicle-carousel");if(carousel)carousel.dataset.swipeStart=String(event.clientX);});
document.addEventListener("pointerup",event=>{const carousel=event.target.closest(".vehicle-carousel"),start=Number(carousel?.dataset.swipeStart);if(!carousel||!Number.isFinite(start))return;delete carousel.dataset.swipeStart;const distance=event.clientX-start;if(Math.abs(distance)<45)return;const current=[...carousel.querySelectorAll("[data-gallery-slide]")].findIndex(slide=>slide.classList.contains("is-active"));updateVehicleCarousel(current+(distance<0?1:-1));});
document.querySelector(".menu-toggle").addEventListener("click",event=>{const nav=document.querySelector(".main-nav"),open=nav.classList.toggle("open");event.currentTarget.setAttribute("aria-expanded",open);});
document.querySelector("#compare-close").addEventListener("click",()=>{state.compare.clear();updateCompare();renderRoute();});
